R process(IN in, OUT out, long OFFSET?, long LIMIT?) throws IOException {
  byte[] BUF = REUSABLE_BUF; // size >= max(K, KEY.length, typical chunk)
  if (isSeekable(in) && getPos(in) != OFFSET) seek(in, OFFSET);

  // Fast path for fixed-size primitive reads
  if (FIXED_LEN_K) {
    readFully(in, BUF, 0, K);
    ACC acc = ASSEMBLE_FIXED(BUF, 0, K); // e.g., mask & shift multiples of 8
    return FINISH(acc);
  }

  // General buffered scan/copy path
  int carry = 0; long done = 0; ACC acc = ACC_INIT;
  for (int n; (n = in.read(BUF, carry, BUF.length - carry)) > 0 && (LIMIT == UNBOUND || done < LIMIT); ) {
    int end = carry + n;
    // Scan/assemble within buffer (keyword matching, state machine, or batch processing)
    int consumed = SCAN_OR_ASSEMBLE(BUF, 0, end, acc, KEY, out);

    // Preserve boundary prefix for next iteration (e.g., partial keyword match)
    int tail = end - consumed;
    if (tail > 0) System.arraycopy(BUF, consumed, BUF, 0, tail);
    carry = tail;
    done += n;
  }
  if (PUSHBACK_NEEDED(acc, KEY)) unread(in, BUF, 0, carry);
  return FINISH(acc);
}

void readFully(IN in, byte[] a, int off, int len) throws IOException {
  while (len > 0) {
    int c = in.read(a, off, len);
    if (c < 0) THROW_EOF();
    off += c; len -= c;
  }
}

