class Context {
  // One of the following indexes is maintained per long-lived context or namespace
  Map<K, A> eqIndex;                 // equality index (e.g., name -> alt/index)
  Map<G, NavigableMap<X, NavigableSet<Y>>> rangeIndex; // ordered 1D/2D numeric index for tolerance/range queries
  IntervalIndex<T, V> intervalIndex; // interval/segment tree for point-in-range queries
}

R query(Context ctx, Q q) {
  switch (INDEX_KIND) {
    case EQUALITY: {
      K k = KEY_OF(q);                 // canonical, stable key
      A a = ctx.eqIndex.get(k);        // e.g., alt or its position
      return a != null ? OUT.fromExact(a) : OUT.emptyOrThrow();
    }
    case ORDERED_RANGE: {
      G g = GROUP_OF(q);               // optional bucket key
      X x = X_OF(q); Y y = Y_OF(q); D tol = TOL_OF(q);
      NavigableMap<X, NavigableSet<Y>> xm = ctx.rangeIndex.get(g);
      if (xm == null) return OUT.empty();
      for (NavigableSet<Y> ys : xm.subMap(x - tol, true, x + tol, true).values()) {
        if (!ys.subSet(y - tol, true, y + tol, true).isEmpty()) return OUT.nearDuplicate();
      }
      // optionally record q to the index if needed
      xm.computeIfAbsent(x, xx -> new java.util.TreeSet<>()).add(y);
      return OUT.notDuplicate();
    }
    case INTERVAL: {
      T point = POINT_OF(q);
      Collection<V> vs = ctx.intervalIndex.query(point);
      return OUT.fromCollection(vs);
    }
  }
  throw new IllegalStateException();
}

// Index build/maintenance (performed once per context or incrementally on updates)
void buildEqIndex(Context ctx, List<E> alts) {
  ctx.eqIndex = new java.util.HashMap<>();
  int i = 0;
  for (E e : alts) {
    K k = KEY_OF_E(e);
    if (ctx.eqIndex.put(k, A.from(e, i++)) != null) throw new IllegalArgumentException("duplicate key");
  }
}

void addInterval(Context ctx, Range<T> r, V v) { ctx.intervalIndex.add(r, v); }

